/**
 * Decimal-digit values for every Unicode `Nd` code point, the way CPython's
 * `Py_UNICODE_TODECIMAL` sees them.
 *
 * `int("１٢")` is 12 in Python: any `Nd` code point counts as a digit
 * and scripts may even be mixed inside one numeral.  Unicode lays `Nd` out as
 * runs of exactly ten consecutive code points whose values are 0..9, so a table
 * of run starts ("the zero of each run") is enough to recover a digit's value.
 *
 * The table below was generated by walking the whole code-point space with
 * `/\p{Nd}/u` (Unicode 15.0) and cutting each maximal consecutive block into
 * ten-code-point runs; every block's length was verified to be a multiple of
 * ten, so run starts are unambiguous even where several runs are adjacent
 * (e.g. the five mathematical-digit runs at U+1D7CE..U+1D7FF).
 */
const DIGIT_RUN_STARTS = [
  0x0030, 0x0660, 0x06f0, 0x07c0, 0x0966, 0x09e6, 0x0a66, 0x0ae6, 0x0b66,
  0x0be6, 0x0c66, 0x0ce6, 0x0d66, 0x0de6, 0x0e50, 0x0ed0, 0x0f20, 0x1040,
  0x1090, 0x17e0, 0x1810, 0x1946, 0x19d0, 0x1a80, 0x1a90, 0x1b50, 0x1bb0,
  0x1c40, 0x1c50, 0xa620, 0xa8d0, 0xa900, 0xa9d0, 0xa9f0, 0xaa50, 0xabf0,
  0xff10, 0x104a0, 0x10d30, 0x11066, 0x110f0, 0x11136, 0x111d0, 0x112f0,
  0x11450, 0x114d0, 0x11650, 0x116c0, 0x11730, 0x118e0, 0x11950, 0x11c50,
  0x11d50, 0x11da0, 0x11f50, 0x16a60, 0x16ac0, 0x16b50, 0x1d7ce, 0x1d7d8,
  0x1d7e2, 0x1d7ec, 0x1d7f6, 0x1e140, 0x1e2f0, 0x1e4f0, 0x1e950, 0x1fbf0,
];

/**
 * Decimal value 0..9 of `codePoint`, or -1 when it is not a decimal digit.
 *
 * ASCII is short-circuited because it is overwhelmingly the common case; every
 * other run is found by binary search over the run-start table.
 */
export function decimalValue(codePoint) {
  if (codePoint >= 0x30 && codePoint <= 0x39) return codePoint - 0x30;

  let lo = 0;
  let hi = DIGIT_RUN_STARTS.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const start = DIGIT_RUN_STARTS[mid];
    if (codePoint < start) hi = mid - 1;
    else if (codePoint > start + 9) lo = mid + 1;
    else return codePoint - start;
  }
  return -1;
}

/** True when `codePoint` is a Unicode decimal digit (general category Nd). */
export function isDecimalDigit(codePoint) {
  return decimalValue(codePoint) >= 0;
}

export { DIGIT_RUN_STARTS };

