/**
 * Python-compatible `repr()` for strings, plus the small amount of value
 * formatting the program needs (`print` of a list, `print` of an int).
 */

/**
 * `str.isprintable()`: false for the Unicode "Other" (Cc, Cf, Cs, Co, Cn) and
 * "Separator" (Zs, Zl, Zp) categories, with ASCII space as the one exception.
 */
const NONPRINTABLE_RE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zs}\p{Zl}\p{Zp}]/u;

function isPrintableCodePoint(codePoint) {
  if (codePoint === 0x20) return true;
  return !NONPRINTABLE_RE.test(String.fromCodePoint(codePoint));
}

function hexEscape(codePoint) {
  if (codePoint < 0x100) return '\\x' + codePoint.toString(16).padStart(2, '0');
  if (codePoint < 0x10000) return '\\u' + codePoint.toString(16).padStart(4, '0');
  return '\\U' + codePoint.toString(16).padStart(8, '0');
}

/**
 * `repr(s)` for a Python `str`.
 *
 * Quote choice mirrors CPython: single quotes normally, double quotes when the
 * string contains a single quote but no double quote (so the quote itself need
 * not be escaped).
 */
export function pyReprStr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";

  let out = quote;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === quote || ch === '\\') out += '\\' + ch;
    else if (ch === '\t') out += '\\t';
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (cp < 0x20 || cp === 0x7f) out += hexEscape(cp);
    else if (cp < 0x7f) out += ch;
    else if (isPrintableCodePoint(cp)) out += ch;
    else out += hexEscape(cp);
  }
  return out + quote;
}

/** `str(int)` / `repr(int)` — plain decimal digits with a leading `-` sign. */
export function pyReprInt(value) {
  return typeof value === 'bigint' ? value.toString(10) : String(value);
}

/** `str(list_of_ints)` — e.g. `[3, 3, 0, 24, 25]`, and `[]` when empty. */
export function pyReprIntList(values) {
  return '[' + values.map(pyReprInt).join(', ') + ']';
}

