import { isPySpace } from './whitespace.mjs';
import { decimalValue } from './unicodedigits.mjs';
import { PyValueError } from './errors.mjs';
import { pyReprStr } from './repr.mjs';

/**
 * `int(s)` for base 10, returned as a BigInt.
 *
 * BigInt rather than Number because Python integers are unbounded and the
 * program feeds these values straight into a bitwise checksum: `int()` happily
 * accepts a 200-bit literal, and the checksum's XOR/shift chain must see every
 * one of those bits.
 *
 * Grammar (CPython `PyLong_FromUnicodeObject`):
 *
 *     space* [+-]? digit ( '_'? digit )* space*
 *
 * where `space` is Python's whitespace set and `digit` is any Unicode decimal
 * digit — so `" -1_0 "` is -10, `"１٢"` is 12, and `"_1"`, `"1_"`, `"1__0"`,
 * `"0x10"`, `"1.0"`, `"- 1"` and `""` all raise.
 */
export function pyInt(s) {
  const codePoints = Array.from(s, (ch) => ch.codePointAt(0));
  let i = 0;
  const end = codePoints.length;

  while (i < end && isPySpace(codePoints[i])) i++;

  let negative = false;
  if (i < end && (codePoints[i] === 0x2b || codePoints[i] === 0x2d)) {
    negative = codePoints[i] === 0x2d;
    i++;
  }

  let digits = '';
  let lastWasDigit = false;
  while (i < end) {
    const cp = codePoints[i];
    if (cp === 0x5f) {
      // An underscore is a digit separator: it needs a digit on both sides.
      if (!lastWasDigit) throw invalidLiteral(s);
      lastWasDigit = false;
      i++;
      continue;
    }
    const value = decimalValue(cp);
    if (value < 0) break;
    digits += String(value);
    lastWasDigit = true;
    i++;
  }

  if (digits === '' || !lastWasDigit) throw invalidLiteral(s);

  while (i < end && isPySpace(codePoints[i])) i++;
  if (i !== end) throw invalidLiteral(s);

  const magnitude = BigInt(digits);
  return negative ? -magnitude : magnitude;
}

function invalidLiteral(s) {
  return new PyValueError(
    `invalid literal for int() with base 10: ${pyReprStr(s)}`,
  );
}

