/**
 * `bech32_hrp_expand(hrp)` — the human-readable part, split into its high and
 * low five-bit halves with a zero separator between them:
 *
 *     [cp >> 5 for cp in hrp] + [0] + [cp & 31 for cp in hrp]
 *
 * The unit of iteration is the Unicode code point, matching Python's `for x in
 * hrp` / `ord(x)`: U+1F388 contributes 3996 and 8, not four UTF-8 bytes and not
 * two UTF-16 surrogates. `for...of` over a JS string yields code points, so the
 * astral cases line up without extra work.
 *
 * No masking or range check is applied to the code point, so a non-ASCII HRP
 * yields values above 31 — exactly as the Python function does.
 */
export function bech32HrpExpand(hrp) {
  const high = [];
  const low = [];
  for (const ch of hrp) {
    const cp = ch.codePointAt(0);
    high.push(cp >> 5);
    low.push(cp & 31);
  }
  return [...high, 0, ...low];
}

