    // string could be mistaken for one (none can, here).
    if (NEGATIVE_NUMBER_RE.test(argString)) return null;

    // Anything containing a space cannot be an option string.
    if (argString.includes(' ')) return null;

    return { action: null, optionString: argString, explicitArg: null };
  }

  parseArgs(argv) {
    const { namespace, extras } = this.parseKnownArgs(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  parseKnownArgs(argv) {
    // Classify every token as an option ('O'), a value ('A'), or the `--`
    // separator ('-'); everything after the first `--` is a value.
    const pattern = [];
    const optionTuples = new Map();
    let sawSeparator = false;
    for (let i = 0; i < argv.length; i++) {
      if (sawSeparator) {
        pattern.push('A');
        continue;
      }
      if (argv[i] === '--') {
        pattern.push('-');
        sawSeparator = true;
        continue;
      }
      const tuple = this.parseOptional(argv[i]);
      if (tuple === null) {
        pattern.push('A');
      } else {
        optionTuples.set(i, tuple);
        pattern.push('O');
      }
    }

    const namespace = Object.create(null);
    for (const action of this.actions) namespace[action.dest] = undefined;

    const extras = [];
    const seen = new Set();

    const consumeOptional = (startIndex) => {
      const { action, optionString, explicitArg } = optionTuples.get(startIndex);

      if (action === null) {
        extras.push(argv[startIndex]);
        return startIndex + 1;
      }

      if (explicitArg !== null) {
        if (action.nargs !== 1) {
          this.error(
            `argument ${ArgumentParser.actionName(action)}: ignored explicit argument '${explicitArg}'`,
          );
        }
        this.takeAction(action, [explicitArg], seen, namespace);
        return startIndex + 1;
      }

      // For an optional with nargs=None the nargs pattern is a bare `(A)`:
      // the very next token must be a value, and `--` will not do.
      if (pattern[startIndex + 1] !== 'A') {
        this.error(`argument ${ArgumentParser.actionName(action)}: expected one argument`);
      }
      this.takeAction(action, [argv[startIndex + 1]], seen, namespace);
      return startIndex + 2;
    };

    const optionIndices = [...optionTuples.keys()].sort((a, b) => a - b);
    const maxOptionIndex = optionIndices.length > 0 ? optionIndices[optionIndices.length - 1] : -1;

    let startIndex = 0;
    while (startIndex <= maxOptionIndex) {
      const nextOptionIndex = optionIndices.find((index) => index >= startIndex);
      // There are no positionals, so any token before the next option is extra.
      if (startIndex !== nextOptionIndex) {
        extras.push(...argv.slice(startIndex, nextOptionIndex));
        startIndex = nextOptionIndex;
      }
      startIndex = consumeOptional(startIndex);
    }
    extras.push(...argv.slice(startIndex));

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => ArgumentParser.actionName(action));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return { namespace, extras };
  }

  takeAction(action, argStrings, seen, namespace) {
    seen.add(action);
    if (action.isHelp) throw new ArgparseExit(0, this.formatHelp(), '');
    namespace[action.dest] = argStrings[0];
  }
}

