/**
 * A faithful re-implementation of the slice of CPython 3.12's `argparse` that
 * this program exercises: a parser with only `store` optionals, no positionals,
 * and the default `-h/--help`.
 *
 * The behaviour reproduced here is the part that is easy to get subtly wrong:
 *
 *   - prefix abbreviation (`--h`, `--he` and `--hel` all mean `--help`);
 *   - the `--opt=value` form, including the "ignored explicit argument" error
 *     when a zero-argument action is given one;
 *   - the negative-number rule, which is what makes `--b -1` a value but
 *     `--b -1,2` an unparseable option — including two quirks of the original
 *     regexp: Python's `\d` matches any Unicode decimal digit, and Python's `$`
 *     also matches just before a single trailing newline;
 *   - the "contains a space" escape hatch, which is why `--b '-1 '` is a value;
 *   - `--`, which ends option parsing but is *not* accepted as an optional's
 *     value (for optionals CPython strips the `-` markers out of the nargs
 *     pattern, leaving a bare `(A)`);
 *   - error precedence: missing-required is reported before unrecognized extras.
 */

/** Raised instead of calling `sys.exit()`, so the caller owns all output. */
export class ArgparseExit extends Error {
  constructor(code, stdout = '', stderr = '') {
    super(`argparse exit ${code}`);
    this.name = 'ArgparseExit';
    this.code = code;
    this.stdout = stdout;
    this.stderr = stderr;
  }
}

const PREFIX_CHAR = '-';
const MAX_HELP_POSITION = 24;
const INDENT = 2;

/**
 * `argparse._negative_number_matcher`, i.e. `r'^-\d+$|^-\d*\.\d+$'`, translated
 * to JavaScript. `\d` becomes `\p{Nd}` (Python's `\d` is Unicode-aware for
 * `str` patterns) and `$` becomes `\n?$` (Python's `$` matches before a single
 * trailing newline).
 */
const NEGATIVE_NUMBER_RE =
  /^-\p{Nd}+\n?$|^-\p{Nd}*\.\p{Nd}+\n?$/u;

export class ArgumentParser {
  constructor({ prog }) {
    this.prog = prog;
    this.actions = [];
    this.optionStringActions = new Map();
    this.addArgument(['-h', '--help'], {
      nargs: 0,
      isHelp: true,
      help: 'show this help message and exit',
    });
  }

  addArgument(optionStrings, { nargs = 1, required = false, help, metavar, isHelp = false } = {}) {
    const dest = optionStrings[optionStrings.length - 1].replace(/^-+/, '');
    const action = {
      optionStrings,
      dest,
      nargs,
      required,
      help,
      isHelp,
      metavar: metavar ?? dest.toUpperCase(),
    };
    this.actions.push(action);
    for (const optionString of optionStrings) this.optionStringActions.set(optionString, action);
    return action;
  }

  /** `_get_action_name`: `--b`, or `-h/--help` for a multi-flag action. */
  static actionName(action) {
    return action.optionStrings.join('/');
  }

  formatUsage() {
    const parts = this.actions.map((action) => {
      const invocation =
        action.nargs === 0
          ? action.optionStrings[0]
          : `${action.optionStrings[0]} ${action.metavar}`;
      return action.required ? invocation : `[${invocation}]`;
    });
    return `usage: ${[this.prog, ...parts].join(' ')}\n`;
  }

  formatHelp() {
    const invocations = this.actions.map((action) =>
      action.nargs === 0
        ? action.optionStrings.join(', ')
        : action.optionStrings.map((o) => `${o} ${action.metavar}`).join(', '),
    );
    const actionMaxLength = Math.max(...invocations.map((s) => s.length + INDENT));
    const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);
    const actionWidth = helpPosition - INDENT - 2;

    const lines = [this.formatUsage(), '\n', 'options:\n'];
    this.actions.forEach((action, i) => {
      const invocation = invocations[i];
      if (action.help === undefined) {
        lines.push(`${' '.repeat(INDENT)}${invocation}\n`);
      } else {
        lines.push(
          `${' '.repeat(INDENT)}${invocation.padEnd(actionWidth)}  ${action.help}\n`,
        );
      }
    });
    return lines.join('');
  }

  /** `parser.error()`: usage + message on stderr, exit status 2. */
  error(message) {
    throw new ArgparseExit(2, '', `${this.formatUsage()}${this.prog}: error: ${message}\n`);
  }

  /** `_get_option_tuples`: prefix-abbreviation matching. */
  getOptionTuples(argString) {
    const result = [];
    if (argString.startsWith(PREFIX_CHAR + PREFIX_CHAR)) {
      let optionPrefix = argString;
      let explicitArg = null;
      const eq = argString.indexOf('=');
      if (eq !== -1) {
        optionPrefix = argString.slice(0, eq);
        explicitArg = argString.slice(eq + 1);
      }
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(optionPrefix)) result.push({ action, optionString, explicitArg });
      }
    } else if (argString.startsWith(PREFIX_CHAR)) {
      const optionPrefix = argString;
      const shortOptionPrefix = argString.slice(0, 2);
      const shortExplicitArg = argString.slice(2);
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString === shortOptionPrefix) {
          result.push({ action, optionString, explicitArg: shortExplicitArg });
        } else if (optionString.startsWith(optionPrefix)) {
          result.push({ action, optionString, explicitArg: null });
        }
      }
    }
    return result;
  }

  /**
   * `_parse_optional`: decide whether `argString` names an option.
   * `null` means "treat it as a plain value".
   */
  parseOptional(argString) {
    if (argString === '') return null;
    if (!argString.startsWith(PREFIX_CHAR)) return null;

    const exact = this.optionStringActions.get(argString);
    if (exact) return { action: exact, optionString: argString, explicitArg: null };

    if (argString.length === 1) return null;

    const eq = argString.indexOf('=');
    if (eq !== -1) {
      const optionString = argString.slice(0, eq);
      const action = this.optionStringActions.get(optionString);
      if (action) return { action, optionString, explicitArg: argString.slice(eq + 1) };
    }

    const tuples = this.getOptionTuples(argString);
    if (tuples.length > 1) {
      const options = tuples.map((t) => t.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${options}`);
    }
    if (tuples.length === 1) return tuples[0];

    // A bare negative number is a value, not an option, as long as no option
    // string could be mistaken for one (none can, here).
    if (NEGATIVE_NUMBER_RE.test(argString)) return null;

    // Anything containing a space cannot be an option string.
    if (argString.includes(' ')) return null;

    return { action: null, optionString: argString, explicitArg: null };
  }

  parseArgs(argv) {
    const { namespace, extras } = this.parseKnownArgs(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  parseKnownArgs(argv) {
    // Classify every token as an option ('O'), a value ('A'), or the `--`
    // separator ('-'); everything after the first `--` is a value.
    const pattern = [];
    const optionTuples = new Map();
    let sawSeparator = false;
    for (let i = 0; i < argv.length; i++) {
      if (sawSeparator) {
        pattern.push('A');
        continue;
      }
      if (argv[i] === '--') {
        pattern.push('-');
        sawSeparator = true;
        continue;
      }
      const tuple = this.parseOptional(argv[i]);
      if (tuple === null) {
        pattern.push('A');
      } else {
        optionTuples.set(i, tuple);
        pattern.push('O');
      }
    }

    const namespace = Object.create(null);
    for (const action of this.actions) namespace[action.dest] = undefined;

    const extras = [];
    const seen = new Set();

    const consumeOptional = (startIndex) => {
      const { action, optionString, explicitArg } = optionTuples.get(startIndex);

      if (action === null) {
        extras.push(argv[startIndex]);
        return startIndex + 1;
      }

      if (explicitArg !== null) {
        if (action.nargs !== 1) {
          this.error(
            `argument ${ArgumentParser.actionName(action)}: ignored explicit argument '${explicitArg}'`,
          );
        }
        this.takeAction(action, [explicitArg], seen, namespace);
        return startIndex + 1;
      }

      // For an optional with nargs=None the nargs pattern is a bare `(A)`:
      // the very next token must be a value, and `--` will not do.
      if (pattern[startIndex + 1] !== 'A') {
        this.error(`argument ${ArgumentParser.actionName(action)}: expected one argument`);
      }
      this.takeAction(action, [argv[startIndex + 1]], seen, namespace);
      return startIndex + 2;
    };

    const optionIndices = [...optionTuples.keys()].sort((a, b) => a - b);
    const maxOptionIndex = optionIndices.length > 0 ? optionIndices[optionIndices.length - 1] : -1;

    let startIndex = 0;
    while (startIndex <= maxOptionIndex) {
      const nextOptionIndex = optionIndices.find((index) => index >= startIndex);
      // There are no positionals, so any token before the next option is extra.
      if (startIndex !== nextOptionIndex) {
        extras.push(...argv.slice(startIndex, nextOptionIndex));
        startIndex = nextOptionIndex;
      }
      startIndex = consumeOptional(startIndex);
    }
    extras.push(...argv.slice(startIndex));

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => ArgumentParser.actionName(action));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return { namespace, extras };
  }

  takeAction(action, argStrings, seen, namespace) {
    seen.add(action);
    if (action.isHelp) throw new ArgparseExit(0, this.formatHelp(), '');
    namespace[action.dest] = argStrings[0];
  }
}

