/**
 * UTF-8 decoding with CPython's `surrogateescape` error handler.
 *
 * Python decodes `sys.argv` with the filesystem encoding and
 * `errors='surrogateescape'`, so a byte that cannot be part of a valid UTF-8
 * sequence survives as the lone surrogate U+DC00+byte instead of being replaced.
 * That is observable here: an HRP of the single byte 0xFF expands to
 * `[1767, 0, 31]`, i.e. `ord(...) == 0xDCFF`, where a replacement character
 * would have given `[2047, 0, 29]`.
 *
 * The input is a "byte string": one JavaScript character per byte, as produced
 * by reading a file with the `latin1` encoding.
 */

const REPLACE_BASE = 0xdc00;

function isContinuation(byte) {
  return byte !== undefined && (byte & 0xc0) === 0x80;
}

/** Decode a byte string to a JS string, escaping undecodable bytes. */
export function decodeUtf8SurrogateEscape(byteString) {
  const bytes = [];
  for (let i = 0; i < byteString.length; i++) bytes.push(byteString.charCodeAt(i) & 0xff);

  let out = '';
  let i = 0;
  while (i < bytes.length) {
    const b0 = bytes[i];

    if (b0 < 0x80) {
      out += String.fromCharCode(b0);
      i += 1;
      continue;
    }

    let length = 0;
    let codePoint = 0;
    if (b0 >= 0xc2 && b0 <= 0xdf) {
      length = 2;
      codePoint = b0 & 0x1f;
    } else if (b0 >= 0xe0 && b0 <= 0xef) {
      length = 3;
      codePoint = b0 & 0x0f;
    } else if (b0 >= 0xf0 && b0 <= 0xf4) {
      length = 4;
      codePoint = b0 & 0x07;
    }

    let valid = length !== 0;
    if (valid) {
      for (let k = 1; k < length; k++) {
        if (!isContinuation(bytes[i + k])) {
          valid = false;
          break;
        }
        codePoint = (codePoint << 6) | (bytes[i + k] & 0x3f);
      }
    }
    // Reject overlong forms, the surrogate range, and anything past U+10FFFF —
    // the three cases a strict UTF-8 decoder must not accept.
    if (valid) {
      const minimum = length === 2 ? 0x80 : length === 3 ? 0x800 : 0x10000;
      if (codePoint < minimum) valid = false;
      else if (codePoint >= 0xd800 && codePoint <= 0xdfff) valid = false;
      else if (codePoint > 0x10ffff) valid = false;
    }

    if (valid) {
      out += String.fromCodePoint(codePoint);
      i += length;
    } else {
      // One surrogate per undecodable byte; resume at the next byte.
      out += String.fromCharCode(REPLACE_BASE | b0);
      i += 1;
    }
  }
  return out;
}

