import { readFileSync } from 'node:fs';
import { decodeUtf8SurrogateEscape } from './utf8.mjs';

/**
 * The command-line arguments as Python's `sys.argv[1:]` would see them.
 *
 * `process.argv` has already been decoded as UTF-8 by Node, with undecodable
 * bytes collapsed to U+FFFD; Python instead keeps them as lone surrogates
 * (`surrogateescape`), which changes both the checksum and the `repr()` in an
 * error message. Re-reading the raw bytes from `/proc/self/cmdline` recovers
 * them.
 *
 * `/proc` may be absent (non-Linux, restricted container), so this falls back
 * to `process.argv` whenever the raw read does not line up.
 */
export function pyArgv() {
  const fallback = process.argv.slice(2);
  try {
    const raw = readFileSync('/proc/self/cmdline', 'latin1');
    // The kernel NUL-terminates every entry, so the split leaves a trailing ''.
    const entries = raw.split('\0');
    if (entries[entries.length - 1] === '') entries.pop();
    // `/proc` also lists the interpreter and any options given to it; the user's
    // arguments are the last `process.argv.length - 2` entries.
    if (entries.length < fallback.length) return fallback;
    const userEntries = fallback.length === 0 ? [] : entries.slice(-fallback.length);
    return userEntries.map(decodeUtf8SurrogateEscape);
  } catch {
    return fallback;
  }
}

