/**
 * Render `Traceback (most recent call last): ...` exactly as CPython does.
 *
 * `frames` is innermost-last (the same order Python prints them). Each frame is
 * `{ file, line, name, source, anchorStart, anchorLength }`:
 *   - `source` is printed indented by four spaces, with its own leading
 *     indentation stripped, matching CPython's `traceback` module.
 *   - `anchorStart`/`anchorLength` (optional) add the `^^^^` marker line that
 *     Python 3.11+ draws under the sub-expression that raised. Offsets are
 *     relative to the stripped `source`.
 */
export function formatTraceback(frames, exc) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of frames) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.name}`);
    if (frame.source === undefined) continue;
    lines.push('    ' + frame.source);
    if (frame.anchorLength) {
      lines.push(' '.repeat(4 + frame.anchorStart) + '^'.repeat(frame.anchorLength));
    }
  }
  lines.push(`${exc.pyType}: ${exc.pyMessage}`);
  return lines.join('\n') + '\n';
}

