import { ArgparseExit } from '../py/argparse.mjs';
import { PyValueError, formatTraceback, formatFrozenFailureLine } from '../py/errors.mjs';
import { printLine, writeStderr } from '../py/stdio.mjs';
import { main } from './main.mjs';
import { CONVERSION_TRACEBACK, SCRIPT_NAME } from './constants.mjs';

/**
 * Turn the outcome of `main()` into the process-level behaviour of the frozen
 * Python program: exit 0 on success, 2 for an argparse failure (usage + error on
 * stderr), 1 for an unhandled exception (traceback on stderr, followed by the
 * PyInstaller bootloader's own complaint).
 */
export function run(argv) {
  try {
    main(argv);
    return 0;
  } catch (err) {
    if (err instanceof ArgparseExit) {
      // `--help` writes to stdout and exits 0; `parser.error()` writes to stderr
      // and exits 2.
      if (err.stdout !== '') writeStdoutRaw(err.stdout);
      if (err.stderr !== '') writeStderr(err.stderr);
      return err.code;
    }
    if (err instanceof PyValueError) {
      writeStderr(formatTraceback(CONVERSION_TRACEBACK, err));
      writeStderr(formatFrozenFailureLine(SCRIPT_NAME, process.pid));
      return 1;
    }
    throw err;
  }
}

// `--help` text is already newline-terminated, so it must not gain another one.
function writeStdoutRaw(text) {
  const withoutTrailingNewline = text.endsWith('\n') ? text.slice(0, -1) : text;
  printLine(withoutTrailingNewline);
}

