import { writeSync } from 'node:fs';

/**
 * Synchronous stdio, so that ordering between stdout and stderr survives an
 * immediate `process.exit()` (Node's stream writes to a pipe are asynchronous
 * and can be dropped on exit).
 */

const STDOUT_FD = 1;
const STDERR_FD = 2;

function write(fd, text) {
  if (text === '') return;
  try {
    writeSync(fd, text);
  } catch (err) {
    // A closed/broken pipe is not an error worth reporting: CPython would die
    // with BrokenPipeError, and the exit status is already being decided by the
    // caller.
    if (err && (err.code === 'EPIPE' || err.code === 'EAGAIN')) return;
    throw err;
  }
}

/** `print(value)` — the text plus a single trailing newline, on stdout. */
export function printLine(text) {
  write(STDOUT_FD, text + '\n');
}

/** Write pre-formatted text (already newline-terminated) to stderr. */
export function writeStderr(text) {
  write(STDERR_FD, text);
}

