const raw = (...bytes) => String.fromCharCode(...bytes);

/** bash $'...' quoting of a byte string, so argv arrives byte-for-byte. */
function shQuote(byteString) {
  let out = "$'";
  for (let i = 0; i < byteString.length; i++) {
    out += '\\x' + (byteString.charCodeAt(i) & 0xff).toString(16).padStart(2, '0');
  }
  return out + "'";
}

function normalizeStderr(s) {
  // The PyInstaller bootloader stamps its own pid into the failure line.
  return s.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');
}

function runVia(program, argBytes) {
  const cmd = [program, ...argBytes.map(shQuote)].join(' ');
  const r = spawnSync('/bin/bash', ['-c', cmd], { encoding: 'latin1', maxBuffer: 1 << 26 });
  return { out: r.stdout ?? '', err: normalizeStderr(r.stderr ?? ''), code: r.status };
}

